#include <iostream>

class ClassA { public: ~ClassA() { std::cout << "Destroyed\n"; } };

void leaky_f() {
    ClassA* ptr = new ClassA; // Acquire resource
    std::cout << "Allocated\n";

    // If exception occurs here, stack unwinds...
    throw 42;

    // ...this line is never reached, resource leaks.
    delete ptr; 
}

int main() {
    try {
        leaky_f();
    } catch (...) {
        // Catching the exception
    }
    // Output shows 'Allocated' but not 'Destroyed'
    // Memory is leaked.
}
